    async def watch_positions(self, symbols: Strings = None, since: Int = None, limit: Int = None, params: dict = {}) -> list[Position]:
        """
        watches information on the open positions of the account, the venue pushes a full portfolio snapshot roughly every five seconds

        https://docs.polymarket.com/perps/realtime-updates

        :param str[] [symbols]: list of unified market symbols
        :param int [since]: not used by polymarket watchPositions
        :param int [limit]: not used by polymarket watchPositions
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict[]: a list of `position structures <https://docs.ccxt.com/#/?id=position-structure>`
        """
        await self.load_markets()
        await self.authenticate()
        symbolsNormalized = self.market_symbols(symbols)
        url = self.safe_string(self.urls['api'], 'ws')
        client = self.client(url)
        self.set_positions_cache(client, symbolsNormalized)
        fetchPositionsSnapshot = self.handle_option('watchPositions', 'fetchPositionsSnapshot', True)
        awaitPositionsSnapshot = self.handle_option('watchPositions', 'awaitPositionsSnapshot', True)
        if (fetchPositionsSnapshot is True) and (awaitPositionsSnapshot is True) and (self.positions is None):
            # the portfolio channel pushes one snapshot at subscribe time and
            # then only on changes, so the first call hydrates over rest
            snapshot = await client.future('fetchPositionsSnapshot')
            return self.filter_by_symbols_since_limit(snapshot, symbolsNormalized, since, limit, True)
        subscribeHashes = ['portfolio']
        request = self.send_subscription('sub', ['portfolio'], ['positions'], subscribeHashes, {}, params, subscribeHashes)
        newPositions = await self.watch(url, 'positions', request, 'portfolio')
        if self.newUpdates:
            return self.filter_by_symbols_since_limit(newPositions, symbolsNormalized, since, limit, True)
        return self.filter_by_symbols_since_limit(self.positions, symbolsNormalized, since, limit, True)

    def set_positions_cache(self, client: Client, symbols: Strings = None):
        if self.positions is not None:
            return
        fetchPositionsSnapshot = self.handle_option('watchPositions', 'fetchPositionsSnapshot', True)
        if fetchPositionsSnapshot is True:
            messageHash = 'fetchPositionsSnapshot'
            if not (messageHash in client.futures):
                client.future(messageHash)
                self.spawn(self.load_positions_snapshot, client, messageHash)
        else:
            self.positions = ArrayCacheBySymbolBySide()

    async def load_positions_snapshot(self, client: Client, messageHash: str):
        positions = await self.fetch_positions()
        self.positions = ArrayCacheBySymbolBySide()
        cache = self.positions
        for i in range(0, len(positions)):
            cache.append(positions[i])
        # don't remove the future from the .futures cache
        if messageHash in client.futures:
            future = client.futures[messageHash]
            future.resolve(cache)
        client.resolve(cache, 'positions')

    async def watch_balance(self, params: dict = {}) -> Balances:
        """
        watches the account margin summary, the venue pushes a full portfolio snapshot roughly every five seconds

        https://docs.polymarket.com/perps/realtime-updates

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a `balance structure <https://docs.ccxt.com/#/?id=balance-structure>`
        """
        await self.load_markets()
        await self.authenticate()
        url = self.safe_string(self.urls['api'], 'ws')
        client = self.client(url)
        self.set_balance_cache(client)
        fetchBalanceSnapshot = self.handle_option('watchBalance', 'fetchBalanceSnapshot', True)
        awaitBalanceSnapshot = self.handle_option('watchBalance', 'awaitBalanceSnapshot', True)
        balanceLoaded = ('info' in self.balance)
        if (fetchBalanceSnapshot is True) and (awaitBalanceSnapshot is True) and (not balanceLoaded):
            # the portfolio channel pushes one snapshot at subscribe time and
            # then only on changes, so the first call hydrates over rest
            snapshot = await client.future('fetchBalanceSnapshot')
            return snapshot
        subscribeHashes = ['portfolio']
        request = self.send_subscription('sub', ['portfolio'], ['balance'], subscribeHashes, {}, params, subscribeHashes)
        return await self.watch(url, 'balance', request, 'portfolio')

    def set_balance_cache(self, client: Client):
        balanceLoaded = ('info' in self.balance)
        if balanceLoaded:
            return
        fetchBalanceSnapshot = self.handle_option('watchBalance', 'fetchBalanceSnapshot', True)
        if fetchBalanceSnapshot is True:
            messageHash = 'fetchBalanceSnapshot'
            if not (messageHash in client.futures):
                client.future(messageHash)
                self.spawn(self.load_balance_snapshot, client, messageHash)

    async def load_balance_snapshot(self, client: Client, messageHash: str):
        balance = await self.fetch_balance()
        self.balance = self.extend(self.balance, balance)
        # don't remove the future from the .futures cache
        if messageHash in client.futures:
            future = client.futures[messageHash]
            future.resolve(self.balance)
        client.resolve(self.balance, 'balance')

    def handle_portfolio(self, client: Client, message: dict):
        #
        #     {
        #         "ch": "portfolio",
        #         "ts": 1788546565789,
        #         "sq": 35879860000,
        #         "data": {
        #             "positions": [
        #                 {
        #                     "instrument_id": 6,
        #                     "symbol": "BTC-USD",
        #                     "size": "0.001",
        #                     "entry_price": "79650.0",
        #                     "leverage": 10,
        #                     "cross": true,
        #                     "initial_margin": "7.97",
        #                     "maintenance_margin": "3.99",
        #                     "position_value": "79.65",
        #                     "liquidation_price": "72000.0",
        #                     "unrealized_pnl": "-0.10",
        #                     "return_on_equity": "-0.0125",
        #                     "cumulative_funding": "0.01",
        #                     "adl_index": 0
        #                 }
        #             ],
        #             "margin": {
        #                 "total_account_value": "100.00",
        #                 "available_order_margin": "90.00",
        #                 "total_initial_margin": "10.00",
        #                 "total_maintenance_margin": "5.00",
        #                 "total_position_value": "50.00"
        #             },
        #             "withdrawable": "90.00",
        #             "in_liquidation": false,
        #             "timestamp": 1788546565789
        #         }
        #     }
        #
        data = self.safe_dict(message, 'data', {})
        timestamp = self.safe_integer(data, 'timestamp')
        if self.positions is None:
            self.positions = ArrayCacheBySymbolBySide()
        cache = self.positions
        rows = self.safe_list(data, 'positions', [])
        newPositions = []
        for i in range(0, len(rows)):
            row = self.safe_dict(rows, i, {})
            extended = self.extend(row, {'timestamp': timestamp})
            position = self.parse_position(extended)
            newPositions.append(position)
            cache.append(position)
        client.resolve(newPositions, 'positions')
        margin = self.safe_dict(data, 'margin', {})
        result = {
            'info': data,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
        }
        account = self.account()
        account['total'] = self.safe_string(margin, 'total_account_value')
        account['free'] = self.safe_string(margin, 'available_order_margin')
        account['used'] = self.safe_string(margin, 'total_initial_margin')
        # pUSD is the only collateral asset on the venue
        result['PUSD'] = account
        self.balance = self.safe_balance(result)
        client.resolve(self.balance, 'balance')

    def handle_ack(self, client: Client, message: object):
        #
        # subscribe or unsubscribe acknowledgement
        #
        #     { "id": 1, "data": [ { "status": "ok" } ] }
        #     { "id": 2, "data": [ { "status": "err", "error": "invalid channel" } ] }
        #
        # ping reply
        #
        #     { "id": 99, "ts": 1788546831854, "data": { "status": "ok", "ts": 1788546831854, "sq": 35879934302 } }
        #
        id = self.safe_string(message, 'id')
        data = self.safe_value(message, 'data')
        if not isinstance(data, list):
            # post replies carry a data object - the auth op is matched back
            # through its pending entry, anything else counts like a pong
            if id is not None:
                postKey = 'req:' + id
                postPending = self.safe_dict(client.subscriptions, postKey)
                if postPending is not None:
                    del client.subscriptions[postKey]
                    postAction = self.safe_string(postPending, 'method')
                    if postAction == 'auth':
                        authStatus = self.safe_string(data, 'status')
                        if authStatus == 'ok':
                            # resolve the future object directly so it stays
                            # cached and later authenticate calls reuse it
                            future = self.safe_value(client.futures, 'authenticated')
                            if future is not None:
                                future.resolve(True)
                        else:
                            authError = AuthenticationError(self.id + ' authentication failed ' + self.json(data))
                            client.reject(authError, 'authenticated')
                            if 'authenticated' in client.subscriptions:
                                del client.subscriptions['authenticated']
                        return
            client.lastPong = self.safe_integer(message, 'ts', self.milliseconds())
            return
        if id is None:
            return
        key = 'req:' + id
        pending = self.safe_dict(client.subscriptions, key)
        if pending is None:
            return
        del client.subscriptions[key]
        messageHashes = self.safe_list(pending, 'messageHashes', [])
        subMessageHashes = self.safe_list(pending, 'subMessageHashes', [])
        action = self.safe_string(pending, 'method')
        errorMessage = None
        for i in range(0, len(data)):
            entry = self.safe_dict(data, i, {})
            status = self.safe_string(entry, 'status')
            if status == 'err':
                errorMessage = self.safe_string(entry, 'error')
        if errorMessage is not None:
            error = ExchangeError(self.id + ' ' + errorMessage)
            for i in range(0, len(messageHashes)):
                client.reject(error, messageHashes[i])
                # clearing the awaited hash lets a later call resend, and a
                # failed subscribe must also clear the shared hash the base
                # watch registered - a failed unsubscribe keeps the live
                # subscription untouched instead
                messageHash = messageHashes[i]
                if messageHash in client.subscriptions:
                    del client.subscriptions[messageHash]
                if action == 'sub':
                    subMessageHash = subMessageHashes[i]
                    if subMessageHash in client.subscriptions:
                        del client.subscriptions[subMessageHash]
            return
        if action == 'unsub':
            topic = self.safe_string(pending, 'topic')
            symbol = self.safe_string(pending, 'symbol')
            if symbol is not None:
                if topic == 'orderbook':
                    if symbol in self.orderbooks:
                        del self.orderbooks[symbol]
                elif topic == 'trades':
                    if symbol in self.trades:
                        del self.trades[symbol]
                elif topic == 'ticker':
                    if symbol in self.tickers:
                        del self.tickers[symbol]
                elif topic == 'ohlcv':
                    timeframe = self.safe_string(pending, 'timeframe')
                    if (timeframe is not None) and (symbol in self.ohlcvs):
                        if timeframe in self.ohlcvs[symbol]:
                            del self.ohlcvs[symbol][timeframe]
            for i in range(0, len(messageHashes)):
                self.clean_unsubscription(client, subMessageHashes[i], messageHashes[i])

    def handle_message(self, client: Client, message: object):
        ch = self.safe_string(message, 'ch')
        if ch is None:
            self.handle_ack(client, message)
            return
        parts = ch.split('::')
        family = self.safe_string(parts, 0, '')
        methods = {
            'book': self.handle_order_book,
            'bbo': self.handle_bid_ask,
            'trades': self.handle_trades,
            'tickers': self.handle_ticker,
            'klines': self.handle_ohlcv,
            'orders': self.handle_order,
            'fills': self.handle_my_trades,
            'portfolio': self.handle_portfolio,
        }
        method = self.safe_value(methods, family)
        if method is not None:
            method(client, message)

    def ping(self, client: Client):
        return {
            'id': self.request_id(),
            'req': 'post',
            'op': {
                'type': 'ping',
            },
        }
